package qr

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.params.ParameterizedTest
import org.junit.jupiter.params.provider.Arguments
import org.junit.jupiter.params.provider.MethodSource
import java.util.zip.CRC32

/**
 * Guards that [TestImages.readLuma] produces byte-identical luma to the JS test readers
 * (jpg.ts `decodeJPEGLuma` / png.ts `decodePNGLuma`). Expected values in
 * src/test/resources/boofcv-luma-crc32.json are generated by node from the JS sources.
 */
class LumaParityTest {
    companion object {
        private val ENTRY = Regex("\"([^\"]+)\"\\s*:\\s*\\{\\s*\"w\"\\s*:\\s*(\\d+)\\s*,\\s*\"h\"\\s*:\\s*(\\d+)\\s*,\\s*\"crc\"\\s*:\\s*\"([0-9a-f]{8})\"\\s*\\}")

        @JvmStatic
        fun entries(): List<Arguments> {
            val text = LumaParityTest::class.java.getResource("/boofcv-luma-crc32.json")!!.readText()
            val list = ENTRY.findAll(text).map { m ->
                Arguments.of(m.groupValues[1], m.groupValues[2].toInt(), m.groupValues[3].toInt(), m.groupValues[4])
            }.toList()
            check(list.size == 539) { "expected 539 luma entries, got ${list.size}" }
            return list
        }
    }

    @ParameterizedTest(name = "{0}")
    @MethodSource("entries")
    fun lumaMatchesJs(path: String, w: Int, h: Int, crc: String) {
        val img = TestImages.readLuma(path)
        assertEquals(w, img.width, "width")
        assertEquals(h, img.height, "height")
        assertEquals(w * h, img.data.size, "luma is 1 byte/pixel")
        val c = CRC32().apply { update(img.data) }.value
        assertEquals(crc, "%08x".format(c), "luma CRC32")
    }
}
